import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"Favorites","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/favorites.md","filePath":"user-guide/settings/favorites.md","lastUpdated":1785993908000}'),i={name:"user-guide/settings/favorites.md"};function o(n,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="favorites" tabindex="-1">Favorites <a class="header-anchor" href="#favorites" aria-label="Permalink to &quot;Favorites&quot;">​</a></h1><p>Pin frequently-used folders, files, or URLs so they&#39;re always one keystroke away.</p><h2 id="adding-a-favorite" tabindex="-1">Adding a favorite <a class="header-anchor" href="#adding-a-favorite" aria-label="Permalink to &quot;Adding a favorite&quot;">​</a></h2><ul><li><strong>Display Name</strong> — optional; if left blank and the target is a local path, it&#39;s auto-filled from the path&#39;s filename.</li><li><strong>Target Path</strong> — a local path, or an <code>http://</code>/<code>https://</code> URL.</li><li><strong>Browse Folder</strong> / <strong>Browse File</strong> buttons open a native picker instead of typing the path.</li><li><strong>Add</strong> button — enabled once a path is entered.</li></ul><h2 id="managing-the-list" tabindex="-1">Managing the list <a class="header-anchor" href="#managing-the-list" aria-label="Permalink to &quot;Managing the list&quot;">​</a></h2><p>Each favorite in the list shows its name and target path, with per-row actions:</p><ul><li><strong>Move Up</strong> / <strong>Move Down</strong> — reorders the list, which also affects how favorites rank against other search results. Each row can also be dragged directly by the six-dot handle on its left edge — the same drag-to-reorder handle used by every other reorderable list in Settings (Result Type Priority, Quick Navigation Order, Sidebar Filter Order, and Results Grid Column Order).</li><li><strong>Edit</strong> — loads the item back into the fields above for changes.</li><li><strong>Remove</strong> — deletes it.</li></ul><h2 id="how-favorites-show-up-in-search" tabindex="-1">How favorites show up in search <a class="header-anchor" href="#how-favorites-show-up-in-search" aria-label="Permalink to &quot;How favorites show up in search&quot;">​</a></h2><p>A matching favorite appears in results with a <strong>★</strong> marker next to its folder/path label, and is searchable by its display name — including pinyin, if the name contains Chinese characters, the same as any other result. This is Lertaro&#39;s closest equivalent to a custom search alias; see <a href="./../search-syntax.html#favorites-not-custom-aliases">Search Syntax</a>.</p>',9)])])}const u=a(i,[["render",o]]);export{f as __pageData,u as default};
